-- Additive live email/postal quotes and cumulative sub-cent EUR settlement. No historical repricing.
CREATE TABLE trusted_delivery_costs(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), sender_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','postal')), provider TEXT NOT NULL CHECK((channel='email' AND provider='ses') OR (channel='postal' AND provider='pingen')), account_id TEXT NOT NULL CHECK(length(account_id) BETWEEN 1 AND 200), route_id TEXT NOT NULL CHECK(length(route_id) BETWEEN 1 AND 200), options_json TEXT NOT NULL CHECK(json_valid(options_json)), rate_json TEXT NOT NULL CHECK(json_valid(rate_json)), base_numerator INTEGER NOT NULL CHECK(typeof(base_numerator)='integer' AND base_numerator BETWEEN 0 AND 1000000000000000), byte_numerator INTEGER NOT NULL CHECK(typeof(byte_numerator)='integer' AND byte_numerator BETWEEN 0 AND 1000000000), rate_denominator INTEGER NOT NULL CHECK(typeof(rate_denominator)='integer' AND rate_denominator BETWEEN 1 AND 1000000000), currency TEXT NOT NULL CHECK(currency='EUR'), fiscal_basis TEXT NOT NULL CHECK(fiscal_basis='qualified_final_variable_cost'), quote_ttl_seconds INTEGER NOT NULL CHECK(quote_ttl_seconds BETWEEN 30 AND 900), source_reference TEXT NOT NULL CHECK(length(source_reference) BETWEEN 1 AND 500), source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64), valid_from TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>valid_from), status TEXT NOT NULL CHECK(status IN ('qualified','revoked')), created_at TEXT NOT NULL, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,sender_id) REFERENCES senders(organization_id,id));
CREATE UNIQUE INDEX qualified_delivery_route ON trusted_delivery_costs(organization_id,sender_id,channel,account_id,route_id,options_json) WHERE status='qualified';
CREATE TRIGGER immutable_delivery_cost BEFORE UPDATE ON trusted_delivery_costs WHEN NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.sender_id IS NOT OLD.sender_id OR NEW.channel IS NOT OLD.channel OR NEW.provider IS NOT OLD.provider OR NEW.account_id IS NOT OLD.account_id OR NEW.route_id IS NOT OLD.route_id OR NEW.options_json IS NOT OLD.options_json OR NEW.rate_json IS NOT OLD.rate_json OR NEW.base_numerator IS NOT OLD.base_numerator OR NEW.byte_numerator IS NOT OLD.byte_numerator OR NEW.rate_denominator IS NOT OLD.rate_denominator OR NEW.currency IS NOT OLD.currency OR NEW.fiscal_basis IS NOT OLD.fiscal_basis OR NEW.quote_ttl_seconds IS NOT OLD.quote_ttl_seconds OR NEW.source_reference IS NOT OLD.source_reference OR NEW.source_sha256 IS NOT OLD.source_sha256 OR NEW.valid_from IS NOT OLD.valid_from OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_at IS NOT OLD.created_at OR (OLD.status='revoked' AND NEW.status<>'revoked') BEGIN SELECT RAISE(ABORT,'immutable_delivery_cost'); END;
CREATE TABLE live_delivery_quotes(dispatch_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, policy_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','postal')), provider TEXT NOT NULL, account_id TEXT NOT NULL, route_id TEXT NOT NULL, fingerprint TEXT NOT NULL, dispatch_fingerprint TEXT NOT NULL, input_json TEXT NOT NULL CHECK(json_valid(input_json)), input_fingerprint TEXT NOT NULL, supplier_numerator TEXT NOT NULL, supplier_denominator TEXT NOT NULL, supplier_nanoeur INTEGER NOT NULL CHECK(typeof(supplier_nanoeur)='integer' AND supplier_nanoeur BETWEEN 0 AND 5000000000000), customer_nanoeur INTEGER NOT NULL CHECK(typeof(customer_nanoeur)='integer' AND customer_nanoeur=2*supplier_nanoeur), amount_minor INTEGER NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor=(customer_nanoeur+9999999)/10000000), ceiling_minor INTEGER NOT NULL CHECK(typeof(ceiling_minor)='integer' AND ceiling_minor BETWEEN amount_minor AND 1000000), currency TEXT NOT NULL CHECK(currency='EUR'), price_rule TEXT NOT NULL CHECK(price_rule='supplier_nanoeur_x2_cumulative_cent'), attachment_bytes INTEGER NOT NULL CHECK(typeof(attachment_bytes)='integer' AND attachment_bytes BETWEEN 0 AND 10000000), provider_draft_id TEXT, prepared_letter_id TEXT, evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64), source_reference TEXT NOT NULL, source_sha256 TEXT NOT NULL, fiscal_basis TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>created_at), FOREIGN KEY(organization_id,dispatch_id) REFERENCES dispatches(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,policy_id) REFERENCES trusted_delivery_costs(organization_id,id));
CREATE TRIGGER immutable_delivery_quote BEFORE UPDATE ON live_delivery_quotes BEGIN SELECT RAISE(ABORT,'immutable_delivery_quote'); END;
CREATE VIEW valid_live_delivery_quotes AS SELECT q.*,p.valid_from AS policy_valid_from,p.expires_at AS policy_expires_at FROM live_delivery_quotes q JOIN dispatches d ON d.organization_id=q.organization_id AND d.id=q.dispatch_id JOIN trusted_delivery_costs p ON p.organization_id=q.organization_id AND p.id=q.policy_id JOIN senders s ON s.organization_id=d.organization_id AND s.id=d.sender_id LEFT JOIN documents doc ON doc.organization_id=d.organization_id AND doc.id=d.document_id WHERE d.mode='production' AND d.channel=q.channel AND d.quote_fingerprint=q.fingerprint AND d.fingerprint=q.dispatch_fingerprint AND p.status='qualified' AND p.sender_id=d.sender_id AND p.channel=d.channel AND p.provider=q.provider AND p.account_id=q.account_id AND p.route_id=q.route_id AND s.status='verified' AND s.mode='production' AND s.channel=d.channel AND s.address=d.sender_address AND (d.document_id IS NULL OR (doc.status='ready' AND doc.sha256=json_extract(q.input_json,'$.documentSha256'))) AND q.attachment_bytes=COALESCE(doc.size,0) AND q.amount_minor=d.estimated_minor AND q.ceiling_minor=d.ceiling_minor AND q.currency=d.currency AND q.source_reference=p.source_reference AND q.source_sha256=p.source_sha256 AND q.fiscal_basis=p.fiscal_basis AND q.expires_at<=p.expires_at AND q.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ',q.created_at,'+'||p.quote_ttl_seconds||' seconds') AND json_extract(q.input_json,'$.channel') IS d.channel AND json_extract(q.input_json,'$.recipient') IS d.recipient_json AND json_extract(q.input_json,'$.documentId') IS d.document_id AND json_extract(q.input_json,'$.senderId') IS d.sender_id AND json_extract(q.input_json,'$.senderAddress') IS d.sender_address AND json_extract(q.input_json,'$.subject') IS d.subject AND json_extract(q.input_json,'$.html') IS d.html AND json_extract(q.input_json,'$.text') IS d.text AND json_extract(q.input_json,'$.options') IS d.options_json AND json_extract(q.input_json,'$.campaignId') IS d.campaign_id AND json_extract(q.input_json,'$.estimatedMinor') IS d.estimated_minor AND json_extract(q.input_json,'$.ceilingMinor') IS d.ceiling_minor AND json_extract(q.input_json,'$.currency') IS d.currency AND json_extract(q.input_json,'$.mode') IS d.mode AND ((d.channel='email' AND p.options_json=d.options_json AND q.provider_draft_id IS NULL AND q.prepared_letter_id IS NULL AND q.supplier_numerator=CAST(p.base_numerator+p.byte_numerator*q.attachment_bytes AS TEXT) AND q.supplier_denominator=CAST(p.rate_denominator AS TEXT) AND q.supplier_nanoeur=(p.base_numerator+p.byte_numerator*q.attachment_bytes+p.rate_denominator-1)/p.rate_denominator AND q.evidence_sha256=p.source_sha256) OR (d.channel='postal' AND doc.id IS NOT NULL AND q.supplier_nanoeur%10000000=0 AND q.supplier_numerator=CAST(q.supplier_nanoeur AS TEXT) AND q.supplier_denominator='1' AND EXISTS(SELECT 1 FROM provider_drafts pd WHERE pd.organization_id=d.organization_id AND pd.id=q.provider_draft_id AND pd.provider='pingen' AND pd.status='prepared' AND pd.provider_id=q.prepared_letter_id AND pd.document_id=doc.id AND pd.document_sha256=doc.sha256 AND pd.sender_id=s.id AND pd.sender_address=s.address AND pd.recipient_json=d.recipient_json AND pd.options_json=p.options_json AND pd.ceiling_minor=d.ceiling_minor AND pd.currency=d.currency AND (pd.claimed_dispatch_id IS NULL OR pd.claimed_dispatch_id=d.id) AND json_extract(d.options_json,'$.providerDraftId')=pd.id AND json_extract(d.options_json,'$.preparedLetterId')=pd.provider_id AND json_extract(d.options_json,'$.expectedAddress')=pd.expected_address AND json_extract(d.options_json,'$.addressPosition')=json_extract(pd.options_json,'$.addressPosition') AND json_extract(d.options_json,'$.deliveryProduct')=json_extract(pd.options_json,'$.deliveryProduct') AND json_extract(d.options_json,'$.printMode')=json_extract(pd.options_json,'$.printMode') AND json_extract(d.options_json,'$.printSpectrum')=json_extract(pd.options_json,'$.printSpectrum'))));
CREATE TRIGGER preparation_live_delivery_quote AFTER INSERT ON live_delivery_quotes BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND policy_valid_from<=NEW.created_at AND policy_expires_at>NEW.created_at); END;
CREATE TRIGGER approval_live_delivery_insert BEFORE INSERT ON approvals WHEN EXISTS(SELECT 1 FROM dispatches WHERE organization_id=NEW.organization_id AND id=NEW.dispatch_id AND mode='production' AND channel IN ('email','postal')) BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND policy_valid_from<=NEW.created_at AND policy_expires_at>NEW.created_at); END;
CREATE TRIGGER approval_live_delivery_update BEFORE UPDATE ON approvals WHEN EXISTS(SELECT 1 FROM dispatches WHERE organization_id=NEW.organization_id AND id=NEW.dispatch_id AND mode='production' AND channel IN ('email','postal')) BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND policy_valid_from<=NEW.created_at AND policy_expires_at>NEW.created_at); END;
CREATE TRIGGER acceptance_live_delivery BEFORE UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' AND NEW.mode='production' AND NEW.channel IN ('email','postal') BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND created_at<=NEW.updated_at AND expires_at>NEW.updated_at AND policy_valid_from<=NEW.updated_at AND policy_expires_at>NEW.updated_at); END;
CREATE TRIGGER preflight_live_delivery BEFORE UPDATE OF status ON dispatches WHEN OLD.status='queued' AND NEW.status='submitting' AND NEW.mode='production' AND NEW.channel IN ('email','postal') BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE (NEW.channel='email' AND NEW.provider IS NOT 'ses') OR (NEW.channel='postal' AND NEW.provider IS NOT 'pingen'); SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND created_at<=NEW.updated_at AND expires_at>NEW.updated_at AND policy_valid_from<=NEW.updated_at AND policy_expires_at>NEW.updated_at); END;
CREATE TABLE delivery_charge_entries(organization_id TEXT NOT NULL REFERENCES welcome_credit_grants(organization_id) ON DELETE CASCADE, dispatch_id TEXT NOT NULL, amount_nanoeur INTEGER NOT NULL CHECK(typeof(amount_nanoeur)='integer' AND amount_nanoeur BETWEEN 0 AND 50000000000), charged_minor INTEGER NOT NULL CHECK(typeof(charged_minor)='integer' AND charged_minor BETWEEN 0 AND 5000), created_at TEXT NOT NULL, PRIMARY KEY(organization_id,dispatch_id));
CREATE TRIGGER immutable_delivery_charge BEFORE UPDATE ON delivery_charge_entries BEGIN SELECT RAISE(ABORT,'immutable_delivery_charge'); END;
CREATE TRIGGER retained_delivery_charge BEFORE DELETE ON delivery_charge_entries WHEN EXISTS(SELECT 1 FROM welcome_credit_grants WHERE organization_id=OLD.organization_id) BEGIN SELECT RAISE(ABORT,'immutable_delivery_charge'); END;
CREATE TRIGGER valid_delivery_charge BEFORE INSERT ON delivery_charge_entries BEGIN SELECT RAISE(ABORT,'delivery_charge_invalid') WHERE NEW.charged_minor<>((COALESCE((SELECT SUM(amount_nanoeur) FROM delivery_charge_entries WHERE organization_id=NEW.organization_id),0)+NEW.amount_nanoeur+9999999)/10000000-(COALESCE((SELECT SUM(amount_nanoeur) FROM delivery_charge_entries WHERE organization_id=NEW.organization_id),0)+9999999)/10000000) OR NOT EXISTS(SELECT 1 FROM live_delivery_quotes q JOIN welcome_credit_reservations r ON r.organization_id=q.organization_id AND r.dispatch_id=q.dispatch_id WHERE q.organization_id=NEW.organization_id AND q.dispatch_id=NEW.dispatch_id AND r.status='settled' AND q.customer_nanoeur=NEW.amount_nanoeur AND NEW.charged_minor<=r.charge_minor); END;
DROP TRIGGER welcome_credit_entry_guard;
CREATE TRIGGER welcome_credit_entry_guard BEFORE INSERT ON welcome_credit_entries BEGIN
 SELECT RAISE(ABORT,'credit_entry_invalid') WHERE NOT EXISTS(SELECT 1 FROM welcome_credit_reservations r WHERE r.organization_id=NEW.organization_id AND r.dispatch_id=NEW.dispatch_id AND r.status=NEW.kind AND ((NEW.kind='reserved' AND NEW.reserved_delta=r.amount_minor AND NEW.spent_delta=0) OR (NEW.kind='settled' AND NEW.reserved_delta=-r.amount_minor AND NEW.spent_delta=COALESCE((SELECT charged_minor FROM delivery_charge_entries n WHERE n.organization_id=r.organization_id AND n.dispatch_id=r.dispatch_id),r.charge_minor)) OR (NEW.kind='released' AND NEW.reserved_delta=-r.amount_minor AND NEW.spent_delta=0)));
 SELECT RAISE(ABORT,'credit_entry_invalid') WHERE NEW.kind<>'reserved' AND NOT EXISTS(SELECT 1 FROM welcome_credit_entries WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND kind='reserved');
END;
DROP TRIGGER welcome_credit_settlement_entry;
CREATE TRIGGER welcome_credit_settlement_entry AFTER UPDATE ON welcome_credit_reservations WHEN NEW.status='settled' BEGIN
 INSERT INTO delivery_charge_entries(organization_id,dispatch_id,amount_nanoeur,charged_minor,created_at) SELECT NEW.organization_id,NEW.dispatch_id,q.customer_nanoeur,(COALESCE((SELECT SUM(amount_nanoeur) FROM delivery_charge_entries WHERE organization_id=NEW.organization_id),0)+q.customer_nanoeur+9999999)/10000000-(COALESCE((SELECT SUM(amount_nanoeur) FROM delivery_charge_entries WHERE organization_id=NEW.organization_id),0)+9999999)/10000000,NEW.updated_at FROM live_delivery_quotes q WHERE q.organization_id=NEW.organization_id AND q.dispatch_id=NEW.dispatch_id;
 INSERT INTO welcome_credit_entries(organization_id,dispatch_id,kind,reserved_delta,spent_delta,created_at) VALUES(NEW.organization_id,NEW.dispatch_id,'settled',-NEW.amount_minor,COALESCE((SELECT charged_minor FROM delivery_charge_entries WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id),NEW.charge_minor),NEW.updated_at);
 UPDATE usage SET reserved_count=reserved_count-1,confirmed_count=confirmed_count+1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id),confirmed_minor=confirmed_minor+(SELECT charged_minor FROM delivery_charge_entries WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id) WHERE organization_id=NEW.organization_id AND (channel,period) IN (SELECT channel,period FROM reservations WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND status='reserved') AND EXISTS(SELECT 1 FROM delivery_charge_entries WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id);
 UPDATE reservations SET status='confirmed' WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND status='reserved' AND EXISTS(SELECT 1 FROM delivery_charge_entries WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id);
END;
DROP TRIGGER confirm_reservation;
CREATE TRIGGER confirm_reservation AFTER UPDATE OF status ON dispatches WHEN NEW.status IN ('accepted','delivered','printed','handed_to_post','bounced','complained') AND EXISTS(SELECT 1 FROM reservations WHERE dispatch_id=NEW.id AND status='reserved') AND NOT EXISTS(SELECT 1 FROM live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id) BEGIN
 UPDATE usage SET reserved_count=reserved_count-1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id),confirmed_count=confirmed_count+1,confirmed_minor=confirmed_minor+(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id) WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=(SELECT period FROM reservations WHERE dispatch_id=NEW.id);
 UPDATE reservations SET status='confirmed',updated_at=NEW.updated_at WHERE dispatch_id=NEW.id AND status='reserved';
END;
DROP TRIGGER release_reservation;
CREATE TRIGGER release_reservation AFTER UPDATE OF status ON dispatches WHEN NEW.status IN ('cancelled','failed') AND EXISTS(SELECT 1 FROM reservations WHERE dispatch_id=NEW.id AND status='reserved') AND NOT EXISTS(SELECT 1 FROM live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id) BEGIN
 UPDATE usage SET reserved_count=reserved_count-1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id),confirmed_count=confirmed_count,confirmed_minor=confirmed_minor WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=(SELECT period FROM reservations WHERE dispatch_id=NEW.id);
 UPDATE reservations SET status='released',updated_at=NEW.updated_at WHERE dispatch_id=NEW.id AND status='reserved';
END;
CREATE TRIGGER delivery_quota_release AFTER UPDATE ON welcome_credit_reservations WHEN NEW.status='released' AND EXISTS(SELECT 1 FROM live_delivery_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id) BEGIN
 UPDATE usage SET reserved_count=reserved_count-1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id) WHERE organization_id=NEW.organization_id AND (channel,period) IN (SELECT channel,period FROM reservations WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND status='reserved');
 UPDATE reservations SET status='released' WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND status='reserved';
END;
